+}
+
+function WorkspaceOrganizationsForm({ scope, workspaceId, disabled, onStateChange, initialOrganizations }: WorkspaceOrganizationsFieldProps & { initialOrganizations: FacilityOrganizationRead[] }) {
+  const { t } = useTranslation();
+  const queryClient = useQueryClient();
+  const [organizations, setOrganizations] = useState(initialOrganizations);
+  const [ids, setIds] = useState(() => initialOrganizations.map((org) => org.id));
+  const [savedIds, setSavedIds] = useState(ids);
