import { useQuery } from "@tanstack/react-query";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterClass } from "@/types/emr/encounter/encounter";
import workspaceApi from "@/types/workspace/workspaceApi";
import query from "@/Utils/request/query";

/** The backend owns access; saved choices apply across facilities by class. */
export function useEncounterWorkspaces(encounterClass?: EncounterClass) {
  const user = useAuthUser();
  const defaults = useQuery({
    queryKey: ["workspace-user-defaults", user.id, "encounter"],
    queryFn: query(workspaceApi.getUserDefaultAttributes, { silent: true }),
    retry: false,
  });
  const list = useQuery({
    queryKey: ["workspaces", user.id, "encounter"],
    queryFn: async ({ signal }) => {
      const response = await query.paginated(workspaceApi.list, { silent: true })({ signal });
      return response.results;
    },
    retry: false,
  });
  const matchingIds = new Set(
    (defaults.data?.results ?? [])
      .filter(({ attribute, value }) => attribute === "encounter_class" && value === encounterClass)
      .map(({ workspace }) => workspace.id),
  );
  // Joining the accessible list also drops deleted/revoked entries in old caches.
  const matches = (list.data ?? []).filter(({ id }) => matchingIds.has(id));

  return {
    defaults,
    list,
    workspace: !defaults.isError && !list.isError && matches.length === 1 ? matches[0] : undefined,
    hasConflictingDefaults: matches.length > 1,
  };
}
