import { useMutation, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useRef } from "react";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterTab } from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterClass } from "@/types/emr/encounter/encounter";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";
import { WorkspaceRead } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";
import { callApi } from "@/Utils/request/query";

import { EncounterWorkspacePicker } from "./EncounterWorkspacePicker";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

export function EncounterWorkspaceSwitcher({ systemTabs }: { systemTabs: Record<string, EncounterTab> }) {
  const user = useAuthUser();
  const queryClient = useQueryClient();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const currentEncounter = useRef(selectedEncounter?.id);
  currentEncounter.current = selectedEncounter?.id;
  const { defaults, list, workspace } = useEncounterWorkspaces(selectedEncounter?.encounter_class);
  const save = useMutation({
    mutationFn: ({ choice, encounterClass }: { choice: WorkspaceRead; encounterClass: EncounterClass; encounterId: string }) =>
      callApi(workspaceApi.setDefaultAttributes, {
        pathParams: { id: choice.id },
        body: { attribute: "encounter_class", value: encounterClass },
        silent: true,
      }),
    onSuccess: async (_, { choice, encounterId }) => {
      await queryClient.invalidateQueries({ queryKey: ["workspace-user-defaults", user.id] });
      if (currentEncounter.current !== encounterId) return;
      const parsed = parseEncounterWorkspaceTemplate(choice.template, Object.keys(systemTabs));
      const firstPage = parsed.success && parsed.template.pages.find(
        (page) => page.kind === "custom" || (!page.hidden && systemTabs[page.key]?.visible !== false),
      );
      const target = new URL(firstPage ? firstPage.key : "updates", window.location.href);
      target.search = window.location.search;
      target.searchParams.delete("workspace");
      navigate(`${target.pathname}${target.search}`);
    },
  });

  return (
    <EncounterWorkspacePicker
      key={selectedEncounter?.id}
      workspaces={(list.data ?? []).filter((choice) => parseEncounterWorkspaceTemplate(choice.template, Object.keys(systemTabs)).success)}
      workspaceId={workspace?.id}
      isLoading={defaults.isLoading || list.isLoading || isSelectedEncounterLoading}
      isError={defaults.isError || list.isError}
      onRetry={() => { defaults.refetch(); list.refetch(); }}
      onSelect={(choice) => {
        if (!selectedEncounter || isSelectedEncounterLoading || save.isPending) return;
        save.mutate({ choice, encounterClass: selectedEncounter.encounter_class, encounterId: selectedEncounter.id });
      }}
      isSaving={save.isPending}
      saveError={save.isError}
    />
  );
}
